tool_input.command:
node --input-type=module -e "
import { toUtcMs } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
for (const off of [330, -300]) {
  const due = toUtcMs('2026-03-01T09:00', off);
  const r = { id: 1, sent: 0, tz_offset_min: off, due_ms: due };
  // find first minute it becomes due
  let t = due - 12*3600e3; while (!dueReminders([r], t).length) t += 60e3;
  console.log('offset', off, 'intended', new Date(due).toISOString(), 'fires', new Date(t).toISOString());
}
" && node --test test/ 2>&1 | tail -8 && node -v
